### Phase 1: Schema Definition

I've defined the schema to support atomic transfers, an audit trail, and idempotency. I'm using `DECIMAL` (or `NUMERIC` in Spanner) for balances to ensure precision, and a `transactions` table to record every movement of funds.

```sql:conductor/tracks/wallet-transfer-service/schema.sql
-- Wallets table stores current balances
CREATE TABLE wallets (
    user_id VARCHAR(64) PRIMARY KEY,
    balance_micros BIGINT NOT NULL DEFAULT 0,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Transactions table provides the double-entry audit trail
CREATE TABLE transactions (
    transaction_id UUID PRIMARY KEY,
    idempotency_key VARCHAR(128) UNIQUE NOT NULL,
    from_user_id VARCHAR(64) NOT NULL,
    to_user_id VARCHAR(64) NOT NULL,
    amount_micros BIGINT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_from_user FOREIGN KEY (from_user_id) REFERENCES wallets(user_id),
    CONSTRAINT fk_to_user FOREIGN KEY (to_user_id) REFERENCES wallets(user_id)
);

-- Index for looking up history by user
CREATE INDEX idx_transactions_user_id ON transactions(from_user_id, to_user_id);
```

### Phase 1: Repository Interface (Go)

I'm setting up the repository layer in Go. This includes the logic for the deterministic locking order we discussed.

```go:internal/repository/wallet_repository.go
package repository

import (
	"context"
	"database/sql"
	"fmt"
	"sort"
)

type WalletRepository interface {
	TransferFunds(ctx context.Context, idempotencyKey string, fromID, toID string, amount int64) error
	GetBalance(ctx context.Context, userID string) (int64, error)
}

type spannerWalletRepo struct {
	db *sql.DB
}

func NewWalletRepository(db *sql.DB) WalletRepository {
	return &spannerWalletRepo{db: db}
}

func (r *spannerWalletRepo) TransferFunds(ctx context.Context, idempotencyKey string, fromID, toID string, amount int64) error {
	// 1. Deterministic Locking Order to prevent deadlocks
	ids := []string{fromID, toID}
	sort.Strings(ids)

	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// 2. Check Idempotency
	var exists bool
	err = tx.QueryRowContext(ctx, "SELECT EXISTS(SELECT 1 FROM transactions WHERE idempotency_key = $1)", idempotencyKey).Scan(&exists)
	if err != nil {
		return err
	}
	if exists {
		return nil // Already processed
	}

	// 3. Acquire locks in sorted order
	for _, id := range ids {
		_, err := tx.ExecContext(ctx, "SELECT 1 FROM wallets WHERE user_id = $1 FOR UPDATE", id)
		if err != nil {
			return fmt.Errorf("failed to lock wallet %s: %w", id, err)
		}
	}

	// 4. Validate balance
	var balance int64
	err = tx.QueryRowContext(ctx, "SELECT balance_micros FROM wallets WHERE user_id = $1", fromID).Scan(&balance)
	if err != nil {
		return err
	}
	if balance < amount {
		return fmt.Errorf("insufficient funds")
	}

	// 5. Execute Double-Entry Updates
	_, err = tx.ExecContext(ctx, "UPDATE wallets SET balance_micros = balance_micros - $1 WHERE user_id = $2", amount, fromID)
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, "UPDATE wallets SET balance_micros = balance_micros + $1 WHERE user_id = $2", amount, toID)
	if err != nil {
		return err
	}

	// 6. Record Transaction Audit
	_, err = tx.ExecContext(ctx, 
		"INSERT INTO transactions (transaction_id, idempotency_key, from_user_id, to_user_id, amount_micros) VALUES (gen_random_uuid(), $1, $2, $3, $4)",
		idempotencyKey, fromID, toID, amount)
	if err != nil {
		return err
	}

	return tx.Commit()
}

func (r *spannerWalletRepo) GetBalance(ctx context.Context, userID string) (int64, error) {
	var balance int64
	err := r.db.QueryRowContext(ctx, "SELECT balance_micros FROM wallets WHERE user_id = $1", userID).Scan(&balance)
	return balance, err
}
```

