package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestCORSMiddleware(t *testing.T) {
	config := CORSConfig{
		AllowedOrigins: []string{"https://example.com", "https://webapp.example.com"},
		AllowedRegexes: []string{`^https://[a-z0-9-]+\.internal\.example\.com$`},
	}
	mw := NewCORSMiddleware(config)

	tests := []struct {
		name           string
		origin         string
		method         string
		expectedStatus int
		wantAllow      bool
	}{
		{"Exact Match", "https://example.com", "GET", http.StatusOK, true},
		{"Subdomain Match", "https://webapp.example.com", "GET", http.StatusOK, true},
		{"Regex Match", "https://service-1.internal.example.com", "GET", http.StatusOK, true},
		{"Regex Mismatch", "https://evil.internal.example.com.attacker.com", "GET", http.StatusOK, false},
		{"Unauthorized Origin", "https://malicious.com", "GET", http.StatusOK, false},
		{"Preflight Allowed", "https://example.com", "OPTIONS", http.StatusNoContent, true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := httptest.NewRequest(tt.method, "/", nil)
			req.Header.Set("Origin", tt.origin)
			if tt.method == "OPTIONS" {
				req.Header.Set("Access-Control-Request-Method", "POST")
			}

			rr := httptest.NewRecorder()
			handler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				w.WriteHeader(http.StatusOK)
			}))

			handler.ServeHTTP(rr, req)

			if rr.Code != tt.expectedStatus {
				t.Errorf("expected status %d, got %d", tt.expectedStatus, rr.Code)
			}

			hasAllowHeader := rr.Header().Get("Access-Control-Allow-Origin") == tt.origin
			if hasAllowHeader != tt.wantAllow {
				t.Errorf("origin %s: wantAllow %v, but header present: %v", tt.origin, tt.wantAllow, hasAllowHeader)
			}
		})
	}
}
```

#### 2. Implement Middleware (`internal/middleware/cors.go`)

```go:internal/middleware/cors.go
package middleware

import (
	"net/http"
	"regexp"
	"strings"
)

type CORSConfig struct {
	AllowedOrigins []string
	AllowedRegexes []string
}

type corsMiddleware struct {
	origins []string
	regexes []*regexp.Regexp
}

func NewCORSMiddleware(cfg CORSConfig) func(http.Handler) http.Handler {
	c := &corsMiddleware{
		origins: cfg.AllowedOrigins,
	}
	for _, r := range cfg.AllowedRegexes {
		c.regexes = append(c.regexes, regexp.MustCompile(r))
	}

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			origin := r.Header.Get("Origin")
			if origin == "" {
				next.ServeHTTP(w, r)
				return
			}

			if c.isOriginAllowed(origin) {
				w.Header().Set("Access-Control-Allow-Origin", origin)
				w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
				w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Requested-With")
				w.Header().Set("Access-Control-Allow-Credentials", "true")
			}

			if r.Method == http.MethodOptions {
				w.WriteHeader(http.StatusNoContent)
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}

func (c *corsMiddleware) isOriginAllowed(origin string) bool {
	for _, o := range c.origins {
		if o == origin {
			return true
		}
	}
	for _, re := range c.regexes {
		if re.MatchString(origin) {
			return true
		}
	}
	return false
}
```

