async function transfer(sourceId: string, destId: string, amount: number, idempotencyKey: string) {
  // 1. Sort IDs to ensure deterministic locking order
  const [firstId, secondId] = [sourceId, destId].sort((a, b) => a.localeCompare(b));

  return await db.transaction(async (tx) => {
    // 2. Acquire locks in the sorted order
    // This ensures that if two users transfer to each other, 
    // they both try to lock the 'smaller' ID first.
    const accountMap = {};
    const firstAcc = await tx.accounts.lock(firstId);
    const secondAcc = await tx.accounts.lock(secondId);

    accountMap[firstAcc.id] = firstAcc;
    accountMap[secondAcc.id] = secondAcc;

    const source = accountMap[sourceId];

    // 3. Business Logic
    if (source.balance < amount) throw new Error("INSUFFICIENT_FUNDS");

    // ... proceed with ledger entries and balance updates ...
  });
}
