### 2. Developer: WalletTransferService Implementation (WLT-T2 & T3)
We will implement the service using a transaction-wrapped method.

**File:** `src/services/WalletTransferService.ts`
```typescript
import { db } from '../db'; // Assume a DB client with transaction support

export class WalletTransferService {
  /**
   * Executes an atomic transfer between two accounts.
   */
  static async transfer(params: {
    sourceUserId: string;
    destinationUserId: string;
    amount: number;
    idempotencyKey: string;
  }) {
    const { sourceUserId, destinationUserId, amount, idempotencyKey } = params;

    if (amount <= 0) throw new Error("INVALID_AMOUNT");
    if (sourceUserId === destinationUserId) throw new Error("SAME_ACCOUNT_TRANSFER");

    return await db.transaction(async (tx) => {
      // 1. Check Idempotency: Has this transaction_id already been processed?
      const existing = await tx.query(
        'SELECT 1 FROM ledger_entries WHERE transaction_id = $1 LIMIT 1',
        [idempotencyKey]
      );
      if (existing.rowCount > 0) {
        return { status: 'SUCCESS', message: 'Already processed (idempotent)' };
      }

      // 2. Fetch Account IDs and Sort for Deadlock Prevention
      const accounts = await tx.query(
        'SELECT id, user_id FROM accounts WHERE user_id IN ($1, $2)',
        [sourceUserId, destinationUserId]
      );

      if (accounts.rowCount < 2) throw new Error("ACCOUNT_NOT_FOUND");

      const sourceAcc = accounts.rows.find(r => r.user_id === sourceUserId);
      const destAcc = accounts.rows.find(r => r.user_id === destinationUserId);

      // Deterministic Sort by UUID string
      const lockOrder = [sourceAcc.id, destAcc.id].sort();

      // 3. Acquire Row Locks in Order
      for (const id of lockOrder) {
        await tx.query('SELECT 1 FROM accounts WHERE id = $1 FOR UPDATE', [id]);
      }

      // 4. Validate Source Balance
      const balanceCheck = await tx.query('SELECT balance FROM accounts WHERE id = $1', [sourceAcc.id]);
      if (balanceCheck.rows[0].balance < amount) {
        throw new Error("INSUFFICIENT_FUNDS");
      }

      // 5. Record Ledger Entries (Double-Entry)
      // Debit Source
      await tx.query(
        'INSERT INTO ledger_entries (transaction_id, account_id, amount, entry_type) VALUES ($1, $2, $3, $4)',
        [idempotencyKey, sourceAcc.id, -amount, 'DEBIT']
      );
      // Credit Destination
      await tx.query(
        'INSERT INTO ledger_entries (transaction_id, account_id, amount, entry_type) VALUES ($1, $2, $3, $4)',
        [idempotencyKey, destAcc.id, amount, 'CREDIT']
      );

      // 6. Update Account Balances
      await tx.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [amount, sourceAcc.id]);
      await tx.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [amount, destAcc.id]);

      return { status: 'SUCCESS', transactionId: idempotencyKey };
    });
  }
}
```

