// internal/repository/wallet/repository.go
package wallet

import (
    "context"
    "database/sql"
    "errors"
)

type Repository struct {
    db *sql.DB
}

func (r *Repository) TransferFunds(ctx context.Context, fromID, toID string, amount int64) (string, error) {
    tx, err := r.db.BeginTx(ctx, nil)
    if err != nil {
        return "", err
    }
    defer tx.Rollback()

    // 1. Deduct from sender (with balance check)
    res, err := tx.ExecContext(ctx, 
        "UPDATE accounts SET balance = balance - $1 WHERE user_id = $2 AND balance >= $1", 
        amount, fromID)
    if err != nil {
        return "", err
    }
    rows, _ := res.RowsAffected()
    if rows == 0 {
        return "", errors.New("insufficient funds or user not found")
    }

    // 2. Add to receiver
    _, err = tx.ExecContext(ctx, 
        "UPDATE accounts SET balance = balance + $1 WHERE user_id = $2", 
        amount, toID)
    if err != nil {
        return "", err
    }

    // 3. Record transaction log (Double Entry)
    var txID string
    err = tx.QueryRowContext(ctx, 
        "INSERT INTO transactions (from_user_id, to_user_id, amount) VALUES ($1, $2, $3) RETURNING id",
        fromID, toID, amount).Scan(&txID)
    if err != nil {
        return "", err
    }

    if err := tx.Commit(); err != nil {
        return "", err
    }

    return txID, nil
}
```

