### 1. Database Schema (PostgreSQL)
To support atomic double-entry and idempotency, we need the following schema:

```sql
CREATE TABLE accounts (
    user_id TEXT PRIMARY KEY,
    balance_cents BIGINT NOT NULL DEFAULT 0,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE transactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    idempotency_key TEXT UNIQUE NOT NULL,
    from_user_id TEXT NOT NULL REFERENCES accounts(user_id),
    to_user_id TEXT NOT NULL REFERENCES accounts(user_id),
    amount_cents BIGINT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
```

### 2. Repository Implementation
This implementation handles the deterministic locking and ensures idempotency via the unique constraint on `idempotency_key`.

```go
// internal/repository/wallet/repository.go
package wallet

import (
    "context"
    "database/sql"
    "errors"
    "fmt"
)

var (
    ErrInsufficientFunds = errors.New("insufficient funds")
    ErrDuplicateRequest  = errors.New("duplicate transaction request")
)

func (r *Repository) TransferFunds(ctx context.Context, fromID, toID string, amount int64, idempotencyKey string) (string, error) {
    tx, err := r.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelReadCommitted})
    if err != nil {
        return "", err
    }
    defer tx.Rollback()

    // 1. Idempotency Check: Check if this key has already been processed
    var existingTxID string
    err = tx.QueryRowContext(ctx, "SELECT id FROM transactions WHERE idempotency_key = $1", idempotencyKey).Scan(&existingTxID)
    if err == nil {
        return existingTxID, nil // Already processed, return original ID
    }

    // 2. Deterministic Locking Order
    firstID, secondID := fromID, toID
    if fromID > toID {
        firstID, secondID = toID, fromID
    }

    // Lock both rows in order
    _, err = tx.ExecContext(ctx, "SELECT 1 FROM accounts WHERE user_id IN ($1, $2) FOR UPDATE", firstID, secondID)
    if err != nil {
        return "", fmt.Errorf("failed to acquire locks: %w", err)
    }

    // 3. Execute Double-Entry Transfer
    // Debit
    res, err := tx.ExecContext(ctx, 
        "UPDATE accounts SET balance_cents = balance_cents - $1 WHERE user_id = $2 AND balance_cents >= $1", 
        amount, fromID)
    if err != nil {
        return "", err
    }
    rows, _ := res.RowsAffected()
    if rows == 0 {
        return "", ErrInsufficientFunds
    }

    // Credit
    _, err = tx.ExecContext(ctx, 
        "UPDATE accounts SET balance_cents = balance_cents + $1 WHERE user_id = $2", 
        amount, toID)
    if err != nil {
        return "", err
    }

    // 4. Record Transaction (Atomic Ledger Entry)
    var txID string
    err = tx.QueryRowContext(ctx, `
        INSERT INTO transactions (idempotency_key, from_user_id, to_user_id, amount_cents) 
        VALUES ($1, $2, $3, $4) 
        RETURNING id`,
        idempotencyKey, fromID, toID, amount).Scan(&txID)
    if err != nil {
        return "", err
    }

    if err := tx.Commit(); err != nil {
        return "", err
    }

    return txID, nil
}
```

### 3. Service Layer Implementation
The service layer maps domain errors to gRPC status codes.

```go
// internal/service/wallet/service.go
func (s *Service) Transfer(ctx context.Context, req *walletv1.TransferRequest) (*walletv1.TransferResponse, error) {
    if req.FromUserId == req.ToUserId {
        return nil, status.Error(codes.InvalidArgument, "sender and receiver must be different")
    }
    if req.AmountCents <= 0 {
        return nil, status.Error(codes.InvalidArgument, "amount must be positive")
    }
    if req.IdempotencyKey == "" {
        return nil, status.Error(codes.InvalidArgument, "idempotency key is required")
    }

    txID, err := s.repo.TransferFunds(ctx, req.FromUserId, req.ToUserId, req.AmountCents, req.IdempotencyKey)
    if err != nil {
        switch {
        case errors.Is(err, wallet.ErrInsufficientFunds):
            return nil, status.Error(codes.FailedPrecondition, err.Error())
        default:
            return nil, status.Errorf(codes.Internal, "transfer failed: %v", err)
        }
    }

    return &walletv1.TransferResponse{
        TransactionId: txID,
    }, nil
}
```

